<div class="content-wrapper"><section class="content-header"><h1>Ekspor Excel Pipanisasi</h1></section><section class="content"><div class="box box-success"><div class="box-body">
<p>Tabel dan unduhan Excel mengikuti periode, pencarian per kolom, dan akses area Anda. Pesanan mengikuti tanggal pembuatan; DO mengikuti tanggal DO.</p>
<form id="pipeline-report-filter" method="get" action="<?= site_url('Pipanisasi/export') ?>"><input type="hidden" name="focus" id="report-focus" value=""><div class="row"><div class="col-sm-4 form-group"><label>Tanggal awal</label><input name="start" type="date" class="form-control" value="<?= html_escape($start) ?>" required></div><div class="col-sm-4 form-group"><label>Tanggal akhir</label><input name="end" type="date" class="form-control" value="<?= html_escape($end) ?>" required></div><div class="col-sm-4" style="padding-top:24px"><button class="btn btn-primary" type="submit">Tampilkan</button> <button class="btn btn-success" name="download" value="1" type="submit">Unduh Excel (.xlsx)</button></div></div></form>
<a href="<?= site_url('Pipanisasi/export').'?'.html_escape(http_build_query(array('start'=>$start,'end'=>$end))) ?>">Reset pencarian kolom</a><p class="text-muted" style="margin-top:10px">Ketik di bawah judul kolom untuk mencari. Beberapa filter dapat digunakan bersamaan. Periode: <?= html_escape($start.' s/d '.$end) ?> (inklusif).</p></div></div>
<style>.pipeline-report-table th{vertical-align:top!important;min-width:145px}.pipeline-report-table th input{margin-top:8px;min-width:130px;font-weight:normal}.pipeline-report-table td{vertical-align:top;overflow-wrap:anywhere}.pipeline-report-table .report-volume{text-align:right;white-space:nowrap}</style>
<?php foreach($datasets as $dataset):list($name,$columns,$rows)=$dataset; ?><div class="box box-primary"><div class="box-header"><h3 class="box-title">Data <?= html_escape($name) ?> · <?= count($rows) ?> dari <?= (int)$totals[$name] ?> baris periode terpilih</h3></div><div class="box-body table-responsive"><table class="table table-bordered table-striped pipeline-report-table" id="report-<?= html_escape($name) ?>"><thead><tr><?php foreach($columns as $key=>$label):$focus=$name.'.'.$key; ?><th scope="col"><label for="filter-<?= html_escape($name.'-'.$key) ?>"><?= html_escape($label) ?></label><input id="filter-<?= html_escape($name.'-'.$key) ?>" form="pipeline-report-filter" name="filters[<?= html_escape($name) ?>][<?= html_escape($key) ?>]" data-focus="<?= html_escape($focus) ?>" class="form-control input-sm report-column-search" type="search" placeholder="Cari <?= html_escape($label) ?>…" aria-label="Cari <?= html_escape($name.' '.$label) ?>" maxlength="200" value="<?= html_escape($filters[$name][$key]??'') ?>"></th><?php endforeach; ?></tr></thead><tbody><?php foreach($rows as $row): ?><tr><?php foreach($columns as $key=>$label): ?><td class="<?= $key==='Quantity'?'report-volume':'' ?>"><?= $key==='Quantity'?rtrim(rtrim(number_format((float)($row[$key]??0),3,',','.'),'0'),','):html_escape($row[$key]??'') ?></td><?php endforeach; ?></tr><?php endforeach;if(!$rows): ?><tr><td colspan="<?= count($columns) ?>" class="text-center text-muted">Tidak ada data sesuai periode dan pencarian.</td></tr><?php endif; ?></tbody></table></div></div><?php endforeach; ?>
</section></div>
<script>(function(){var form=document.getElementById('pipeline-report-filter'),timer=null,focus=document.getElementById('report-focus');function submit(){form.elements.end.setCustomValidity(form.elements.start.value>form.elements.end.value?'Tanggal akhir harus sama atau setelah tanggal awal.':'');if(form.checkValidity())form.submit();else form.reportValidity();}document.querySelectorAll('.report-column-search').forEach(function(input){input.addEventListener('input',function(){clearTimeout(timer);focus.value=input.dataset.focus;timer=setTimeout(submit,650);});input.addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();clearTimeout(timer);focus.value=input.dataset.focus;submit();}});});['start','end'].forEach(function(key){form.elements[key].addEventListener('change',function(){clearTimeout(timer);focus.value='';submit();});});form.addEventListener('submit',function(){clearTimeout(timer);});var previous=new URLSearchParams(window.location.search).get('focus');if(previous){var input=document.getElementById('filter-'+previous.replace('.','-'));if(input&&input.classList.contains('report-column-search')){input.focus();if(input.setSelectionRange)input.setSelectionRange(input.value.length,input.value.length);}}})();</script>
